from collections import defaultdict
from statistics import mean
from random import Random
import json
from vs import corpus,dsl,gaps
from decompose import scenario,score,null_test
def groups(rows,tokens,stride):
 out=[]
 for row in rows:
  bins=defaultdict(list)
  for i in row[1:-1]:
   w=tokens[i]['w'];bins[(len(w),w.count('o'))].append(i)
  out.extend(x for x in bins.values() if len(x)>=2)
 return out

ps={e:corpus.split_pages('practice',e)[0] for e in ('zl','it')}
folios=sorted({p.id for p in ps['zl']} & {p.id for p in ps['it']})[:12]
ps={e:[p for p in x if p.id in folios] for e,x in ps.items()}
ids={e:gaps.eligible_line_ids(x) for e,x in ps.items()}
shared=ids['zl'] & ids['it']
out={'selection':{'method':'first 12 lexicographically sorted practice-training folios shared by ZL and IT, fixed before examining outcomes','folios':folios,'shared_line_ids':len(shared)}}
for e in ps:
 ts=dsl.tokens(scenario(ps[e],shared)); words=[x['w'] for x in ts]
 geometry=dsl._paragraph_gap_groups(ts); rows=dsl._paragraph_gap_groups(ts,by_line=True)
 gg=groups(rows,ts,'length_and_o_count')
 movers=sum(len(g) for g in gg if len({tuple(i for i,c in enumerate(words[x]) if c=='o') for x in g})>1)
 pairs=sum(1 for g in gg for j in range(len(g)) for k in range(j+1,len(g)) if tuple(i for i,c in enumerate(words[g[j]]) if c=='o') != tuple(i for i,c in enumerate(words[g[k]]) if c=='o'))
 total=sum(len(g)*(len(g)-1)//2 for g in gg)
 result={'words':sum(map(len,geometry)),'runs':len(geometry),'groups':len(gg),'slots_in_groups':sum(map(len,gg)),'o_pattern_movable_slots':movers,'o_pattern_changing_pairs':pairs,'eligible_pairs':total,'coefficient':score(words,geometry)}
 for name,g in [('line_inventory',rows),('fixed_edge_length_o_count',gg)]:
  result[name]=null_test(words,geometry,g,n=99,seed=260118)
 # conditional-null synthetic controls: each independently generated null book is a group-wise permutation of original,
 # evaluated with 39 fresh permutations.  Counts are low-resolution exploratory calibration, not proof of size.
 rng=Random(80624); outcomes=[]
 for b in range(20):
  sample=words[:]
  for group in gg:
   vals=[words[i] for i in group];rng.shuffle(vals)
   for i,w in zip(group,vals):sample[i]=w
  outcomes.append(null_test(sample,geometry,gg,n=39,seed=8000+b)['p'])
 result['conditional_null_20_books']={'p_values':outcomes,'reject_at_0.05':sum(p<=.05 for p in outcomes),'draws_per_book':39,'note':'conditional exchangeability check only; no planted effects'}
 out[e]=result
print(json.dumps(out,indent=2))
